reference_solution:
def maximum_balls_in_box(low_limit, high_limit):
 counts={}
 for value in range(low_limit,high_limit+1):
  box=sum(int(digit) for digit in str(value));counts[box]=counts.get(box,0)+1
 return max(counts.values())

